{
  bsv,
  build,
  host ? build,
}:
let
  lib = bsv.lib;
in
lib.bwrapDerivation {
  name = "${build.system}.${host.name}.hello-2.12";

  root = [
    build.stdenv-nocc
    build."${host.name}-toolchain"
  ];

  env = {
    src = lib.fetchTarball {
      url = "https://ftp.gnu.org/gnu/hello/hello-2.12.tar.gz";
      hash = "sha256-zwSvhtwIUmjF9EcPuuSbGK+8Iht4CWqrhC2TSna60Ks=";
    };

    inherit (build) PATH;
    inherit (host) CC CFLAGS LDFLAGS;
  };

  builder = lib.configureMake {
    configureFlags = [
      "--build=${build.triple}"
      "--host=${host.triple}"
      "--libdir=${host.libdir}"
      "--prefix=${host.prefix}"
    ];

    postInstall = ''
      rm --recursive --force $out/${host.prefix}/share
    '';
  };

  unsafeDiscardReferences.out = true;

  system = build.system;
}
