    build."${host.name}-toolchain"
  ];

  env = {
    src = lib.fetchTarball {
      url = "https://ftp.gnu.org/gnu/bc/bc-1.08.2.tar.gz";
      hash = "sha256-rkcP7EKXdWU+BCAV7cko0HyMOy/Fl2UXKjMNPYd4X4Y=";
    };

    inherit (build) PATH;
    inherit (host) CC CFLAGS LDFLAGS;
  };

  builder = lib.configureMake {
    configureFlags = [
      "--build=${build.triple}"
      "--host=${host.triple}"
      "--libdir=${host.libdir}"
      "--prefix=${host.prefix}"
    ];

    makeCommand = "make --directory=lib; make --directory=bc";

    installCommand = "make --directory=bc install";
  };

  unsafeDiscardReferences.out = true;

  system = build.system;
}

