pkgs/linux-gnu.nix:551:    hello = import ./hello/default.nix {
pkgs/linux-gnu.nix:1125:      hello = import ../tests/hello/default.nix {
pkgs/x86_64-apple-darwin18.nix:107:  hello = import ./hello/default.nix {
