=== reports/hello.nix ===
let
  bsv = import ../default.nix;
  x86_64-linux = bsv.legacyPackages.x86_64-linux;
  x86_64-linux-gnu = x86_64-linux.x86_64-linux-gnu;

  elfToolchains = [
    "nds32le-elf-newlib-v5e"
    "nds32le-elf-mculib-v5e"
    "nds32le-elf-newlib-v5"
    "nds32le-elf-newlib-v5f"
    "nds32le-elf-newlib-v5d"
    "nds32le-elf-mculib-v5"
    "nds32le-elf-mculib-v5f"
    "nds32le-elf-mculib-v5d"
    "nds64le-elf-newlib-v5"
    "nds64le-elf-newlib-v5f"
    "nds64le-elf-newlib-v5d"
    "nds64le-elf-mculib-v5"
    "nds64le-elf-mculib-v5f"
    "nds64le-elf-mculib-v5d"
  ];

  linuxToolchains = [
    "nds32le-linux-glibc-v5"
    "nds32le-linux-glibc-v5d"
    "nds64le-linux-glibc-v5"
    "nds64le-linux-glibc-v5d"
    "nds32le-linux-musl-v5"
    "nds32le-linux-musl-v5d"
    "nds64le-linux-musl-v5"
    "nds64le-linux-musl-v5d"
  ];

  allToolchains = elfToolchains ++ linuxToolchains;

  toolchainArchMap = import ../tests/toolchain-arch-map.nix;

  flagsList = [
    "O0"
    "O1"
    "O2"
    "O3"
    "O3-flto-bfd"
    "O3-flto-lld"
    "Og"
    "Os-bfd"
    "Os-lld"
    "Os-flto-bfd"
    "Os-flto-lld"
    "O2-large"
    "Os1-medlow"
    "Os2-medany"
  ];

  table = name: lang: toolchains: compiler: {
    inherit name;

    headers = flagsList;

    rows =
      builtins.map (
        tc:
        let
          toolchain = builtins.elemAt tc 0;
          arch = builtins.elemAt tc 1;
        in
        {
          name = "${toolchain}.${arch}";
          columns = builtins.map (
            cflags: x86_64-linux-gnu.tests.hello.${lang}.${toolchain}.${arch}.${compiler}.${cflags}.qemu or null
          ) flagsList;
        }
      )
      <| builtins.concatMap (
        toolchain:
        builtins.map (arch: [
          toolchain
          arch
        ]) toolchainArchMap.${toolchain}
      ) toolchains;
  };
in
{
  version = "1";
  tables = [
    (table "Hello C Test (GCC)" "c" allToolchains "gcc")
    (table "Hello C Test (Clang)" "c" allToolchains "clang")
    (table "Hello C++ Test (GCC)" "c++" allToolchains "gcc")
    (table "Hello C++ Test (Clang)" "c++" allToolchains "clang")
    (table "Hello Fortran Test (GCC)" "fortran" linuxToolchains "gcc")
  ];
}

