import { TextLineStream } from "@std/streams/text-line-stream";
import { printCommandHelp } from "@bsv/cli/print_command_help.ts";
import { stdoutConsole } from "@bsv/utils/console.ts";
import { runCaptureOutput } from "@bsv/utils/run.ts";

export const help = "Generate hash given a url attribute from stdin.";
export const requiresBsvEnv = true;

export default async (argv: ReadonlyArray<string>): Promise<void> => {
  if (argv.length > 0) {
    printCommandHelp({
      name: "gen-hash",
      synopsis: help,
      usage: "",
    });
    return;
  }

  const lines = Deno.stdin.readable.pipeThrough(new TextDecoderStream())
    .pipeThrough(new TextLineStream());
  for await (const line of lines) {
    const match = line.match(/^( *)url = "([^;]*)";$/);
    if (match) {
      const [_, indent, url] = match;
      const hash =
        (await runCaptureOutput(["nix-prefetch-url", url!], { stderr: "null" }))
          .trim();
      const sriHash = (await runCaptureOutput([
        "nix",
        "hash",
        "convert",
        "--hash-algo",
        "sha256",
        hash,
      ])).trim();
      stdoutConsole.log(line.trimEnd());
      stdoutConsole.log(`${indent}hash = "${sriHash}";`);
    }

    break;

