if (attrs.ccacheDir !== undefined && config.ccache) {
  Deno.mkdirSync("/bsv/tmp/ccache", { recursive: true });
  bwrapArgs.push("--bind-try", "/bsv/tmp/ccache", attrs.ccacheDir);
}

const isBuildShell = Deno.env.get("BSV_BUILD_SHELL") === "1";

if (isBuildShell) {
  bwrapArgs.push(
    "--setenv",
    "PS1",
    Deno.env.get("BSV_BUILD_SHELL_PS1") ?? "",
  );
  const extraArgsJson = Deno.env.get("BSV_BUILD_SHELL_EXTRA_BWRAP_ARGS");
  if (extraArgsJson) {
    const extraArgs = JSON.parse(extraArgsJson);
    bwrapArgs.push(...extraArgs);
  }
  bwrapArgs.push("--", "/bin/sh", "--norc");
  const command = Deno.env.get("BSV_BUILD_SHELL_COMMAND");
  if (command) {
    bwrapArgs.push("-c", command);
  }
} else {
  bwrapArgs.push("--", attrs.env.builder);
}

const removeOutputs = async () => {
  for (const [name, dir] of Object.entries(attrs.outputs)) {
    try {
      await removeAtomically(dir);
    } catch (e) {
      throw new Error(
        `Unable to remove output directory for ${name}: ${dir}`,
        { cause: e },
      );
    }
  }
};

await removeOutputs();

const buildStartTime = performance.now();
try {
  await run(["/bsv/bin/bwrap", ...bwrapArgs]);
} catch (e) {
  if (isBuildShell) {
    return 0;
  }

  if (!config.debug && e instanceof CommandError) {
    console.error("Builder failed with exit code:", e.status.code);
    return e.status.code;
  } else {
    throw e;
  }
}
const buildEndTime = performance.now();

if (!isBuildShell) {
  const duration = (buildEndTime - buildStartTime) / 1000.0;
  await Deno.stderr.write(
    new TextEncoder().encode(`Build took ${duration.toFixed(2)} seconds\n`),
  );

