let
  bsv = import ../../default.nix;
  lib = bsv.lib;
  x86_64-linux-gnu = bsv.legacyPackages.x86_64-linux.x86_64-linux-gnu;
  aarch64-apple-darwin20 = bsv.legacyPackages.x86_64-linux.aarch64-apple-darwin20;
  x86_64-apple-darwin18 = bsv.legacyPackages.x86_64-linux.x86_64-apple-darwin18;
  x86_64-w64-mingw32 = bsv.legacyPackages.x86_64-linux.x86_64-w64-mingw32;

  build = x86_64-linux-gnu;

  darwin-clang-cfg =
    target:
    builtins.toFile "${target.name}-clang-cfg" ''
      -Werror=unguarded-availability
      --target=${target.triple}
      --sysroot=<CFGDIR>/../${target.triple}
      --ld-path=<CFGDIR>/${target.triple}-ld
      -isystem <CFGDIR>/../${target.triple}/include
      --library-directory=<CFGDIR>/../${target.triple}/lib
    '';
in
(import ../linux-gnu.nix { system = "x86_64-linux"; })
// {
  aarch64-apple-darwin20-binutils = import ../darwin-binutils/default.nix {
    inherit bsv build;
    target = aarch64-apple-darwin20;
  };

  aarch64-apple-darwin20-cctools = import ../cctools/default.nix {
    inherit bsv build;
    target = aarch64-apple-darwin20;
  };

  aarch64-apple-darwin20-clang = import ../darwin-clang/default.nix {
    inherit bsv build;
    target = aarch64-apple-darwin20;
  };

  aarch64-apple-darwin20-clang-cfg = darwin-clang-cfg aarch64-apple-darwin20;

  aarch64-apple-darwin20-toolchain = lib.strictUnion {
    name = "x86_64-linux.x86_64-linux-gnu.aarch64-apple-darwin20-toolchain";

    paths = [
      x86_64-linux-gnu.aarch64-apple-darwin20-binutils
      x86_64-linux-gnu.aarch64-apple-darwin20-clang
      aarch64-apple-darwin20.macos-sdk
      aarch64-apple-darwin20.llvm-runtimes
    ];

    unsafeDiscardReferences.out = true;
  };

  wine = import ../wine/default.nix {
    inherit bsv build;
  };

  x86_64-apple-darwin18-binutils = import ../darwin-binutils/default.nix {
    inherit bsv build;
    target = x86_64-apple-darwin18;
  };

  x86_64-apple-darwin18-cctools = import ../cctools/default.nix {
    inherit bsv build;
    target = x86_64-apple-darwin18;
  };

  x86_64-apple-darwin18-clang = import ../darwin-clang/default.nix {
    inherit bsv build;
    target = x86_64-apple-darwin18;
  };

  x86_64-apple-darwin18-clang-cfg = darwin-clang-cfg x86_64-apple-darwin18;

  x86_64-apple-darwin18-toolchain = lib.strictUnion {
    name = "x86_64-linux.x86_64-linux-gnu.x86_64-apple-darwin18-toolchain";

    paths = [
      x86_64-linux-gnu.x86_64-apple-darwin18-binutils
      x86_64-linux-gnu.x86_64-apple-darwin18-clang
      x86_64-apple-darwin18.macos-sdk
      x86_64-apple-darwin18.llvm-runtimes
    ];

    unsafeDiscardReferences.out = true;
  };

  x86_64-w64-mingw32-binutils = import ../x86_64-w64-mingw32-binutils/default.nix {
    inherit bsv;
    build = x86_64-linux-gnu;
  };

  x86_64-w64-mingw32-clang-cfg = builtins.toFile "x86_64-w64-mingw32-clang.cfg" ''
    --target=${x86_64-w64-mingw32.triple}
    --sysroot=<CFGDIR>/../${x86_64-w64-mingw32.triple}
    -isystem <CFGDIR>/../lib64/gcc/${x86_64-w64-mingw32.triple}/14.3.0/include/
    --library-directory=<CFGDIR>/../lib64/gcc/${x86_64-w64-mingw32.triple}/14.3.0/
  '';

  x86_64-w64-mingw32-clang = lib.bwrapDerivation {
    name = "x86_64-linux.x86_64-linux-gnu.x86_64-w64-mingw32-clang";

    root = [ x86_64-linux-gnu.stdenv-nocc ];

    env = {
      inherit (x86_64-linux-gnu) PATH;
    };

    builder = lib.bashBuilder ''
      mkdir --parents $out/${x86_64-linux-gnu.prefix}/bin $out/${x86_64-linux-gnu.prefix}/lib
      cp --archive --verbose ${x86_64-linux-gnu.llvm}/${x86_64-linux-gnu.prefix}/bin/{clang-18,clang,clang++} $out/${x86_64-linux-gnu.prefix}/bin/
      cp --archive --verbose ${x86_64-linux-gnu.llvm}/${x86_64-linux-gnu.prefix}/lib/clang/ $out/${x86_64-linux-gnu.prefix}/lib/
      install -Dm644 ${x86_64-linux-gnu.x86_64-w64-mingw32-clang-cfg} $out/${x86_64-linux-gnu.prefix}/bin/x86_64-w64-mingw32-clang.cfg
      install -Dm644 ${x86_64-linux-gnu.x86_64-w64-mingw32-clang-cfg} $out/${x86_64-linux-gnu.prefix}/bin/x86_64-w64-mingw32-clang++.cfg
      ln --symbolic --force clang $out/${x86_64-linux-gnu.prefix}/bin/x86_64-w64-mingw32-clang
      ln --symbolic --force clang $out/${x86_64-linux-gnu.prefix}/bin/x86_64-w64-mingw32-clang++
    '';

    system = "x86_64-linux";
  };

  x86_64-w64-mingw32-cmake-toolchain-file = builtins.toFile "${x86_64-w64-mingw32.triple}.cmake" ''
    set(CMAKE_SYSTEM_NAME Windows)
    set(CMAKE_SYSTEM_PROCESSOR x86_64)

    set(CMAKE_SYSROOT ${x86_64-w64-mingw32.prefix})

    set(CMAKE_C_COMPILER ${x86_64-w64-mingw32.CC})
    set(CMAKE_CXX_COMPILER ${x86_64-w64-mingw32.CXX})

    set(CMAKE_FIND_ROOT_PATH_MODE_PROGRAM NEVER)
    set(CMAKE_FIND_ROOT_PATH_MODE_LIBRARY ONLY)
    set(CMAKE_FIND_ROOT_PATH_MODE_INCLUDE ONLY)
    set(CMAKE_FIND_ROOT_PATH_MODE_PACKAGE ONLY)
  '';

  # x86_64-w64-mingw32-clang uses native tls by default, which is incompatible
  # with emutls from libstdc++, causing linker errors.
  # Workaround by always compiling with -femulated-tls.
  x86_64-w64-mingw32-cmake-toolchain-file-clang = builtins.toFile "${x86_64-w64-mingw32.triple}.cmake" ''
    set(CMAKE_SYSTEM_NAME Windows)
    set(CMAKE_SYSTEM_PROCESSOR x86_64)

    set(CMAKE_C_COMPILER ${x86_64-w64-mingw32.triple}-clang)
    set(CMAKE_CXX_COMPILER ${x86_64-w64-mingw32.triple}-clang++)
    set(CMAKE_C_FLAGS_INIT -femulated-tls)
    set(CMAKE_CXX_FLAGS_INIT -femulated-tls)

    set(CMAKE_FIND_ROOT_PATH ${x86_64-w64-mingw32.prefix})
    set(CMAKE_FIND_ROOT_PATH_MODE_PROGRAM NEVER)
    set(CMAKE_FIND_ROOT_PATH_MODE_LIBRARY ONLY)
    set(CMAKE_FIND_ROOT_PATH_MODE_INCLUDE ONLY)
    set(CMAKE_FIND_ROOT_PATH_MODE_PACKAGE ONLY)
  '';

  x86_64-w64-mingw32-gcc-stage1 = import ../x86_64-w64-mingw32-gcc-stage1/default.nix {
    inherit bsv;
    build = x86_64-linux-gnu;
    target = x86_64-w64-mingw32;
  };

  x86_64-w64-mingw32-gcc-stage2 = import ../x86_64-w64-mingw32-gcc-stage2/default.nix {
    inherit bsv;
    build = x86_64-linux-gnu;
    target = x86_64-w64-mingw32;
  };

  x86_64-w64-mingw32-meson-cross-file = builtins.toFile "${x86_64-w64-mingw32.triple}.txt" ''
    [binaries]
    ar = '${x86_64-w64-mingw32.triple}-ar'
    c = '${x86_64-w64-mingw32.triple}-gcc'
    cpp = '${x86_64-w64-mingw32.triple}-g++'
    pkg-config = '${x86_64-w64-mingw32.triple}-pkg-config'
    strip = '${x86_64-w64-mingw32.triple}-strip'

    [host_machine]
    cpu = 'x86_64'
    cpu_family = 'x86_64'
    endian = 'little'
    system = 'windows'
  '';

  x86_64-w64-mingw32-pkgconf = import ../pkgconf/default.nix {
    inherit bsv;
    build = x86_64-linux-gnu;
    target = x86_64-w64-mingw32;
  };

  x86_64-w64-mingw32-toolchain = lib.strictUnion {
    name = "x86_64-linux.x86_64-linux-gnu.x86_64-w64-mingw32-toolchain";

    paths = [
      x86_64-linux-gnu.x86_64-w64-mingw32-binutils
      x86_64-linux-gnu.x86_64-w64-mingw32-gcc-stage2
      x86_64-w64-mingw32.headers-no-dummy-pthreads
      x86_64-w64-mingw32.crt
      x86_64-w64-mingw32.winpthreads
    ];

    unsafeDiscardReferences.out = true;
  };
}
