{
  bsv,
  build,
  host ? build,
}:
let
  lib = bsv.lib;
  version = "5.046";
in
lib.bwrapDerivation {
  name = "${build.system}.${host.name}.verilator-${version}";

  root = [
    build.stdenv
    build.autoconf
    build.bison
    build.flex
    build.llvm
    build.m4
    build.perl
    build.python_3_12
  ];

  env = {
    src = lib.fetchGit {
      url = "https://github.com/verilator/verilator";
      ref = "v${version}";
      rev = "d121a673d89d2324a5a49bb4768eed0cebb1819a";
    };
    inherit (build) PATH;
    VERILATOR_SRC_VERSION = "v${version}";
    CC = "clang";
    CXX = "clang++";
  };

  builder = lib.configureMake {
    preConfigure = ''
      cp --archive $src/. .
      chmod --recursive u+w .
      autoconf
    '';

    configureCommand = "./configure";

    configureFlags = [
      "--prefix=${host.prefix}"
    ];

    # we dont really need help2man if not install manpage
    postConfigure = ''
      sed -i 's|help2man|true|g' Makefile
    '';

    installCommand = "make installbin installdata";
  };

  unsafeDiscardReferences.out = true;

  system = build.system;
}
