  lib = bsv.lib;

  triple = lib.parse-triple config.target-triple;

  host = {
    recurseForDerivations = true;

    name = config.name;
    libdir = "${host.prefix}/lib";
    prefix =
      {
        elf = build.andes.${host.name}.sysroot;
        linux = "${build.andes.${host.name}.sysroot}/usr";
      }
      .${triple.os};
    triple = triple;

    config = config // {
      xlen =
        {
          "riscv32" = "32";
          "riscv64" = "64";
        }
        .${triple.machine};
    };

    ${if config.libc == "glibc" then "glibc" else null} = import ./glibc/default.nix {
      inherit bsv build host;
    };

    ${if config.libc == "newlib" then "newlib" else null} = import ./newlib/default.nix {
      inherit bsv build host;
    };

    ${if config.libc == "mculib" then "mculib" else null} = import ./mculib/default.nix {
      inherit bsv build host;
    };

    ${if config.libc == "musl" then "musl" else null} = import ./musl/default.nix {
      inherit bsv build host;
    };

    libc =
      if config.libc == "newlib" then
        host.newlib
      else if config.libc == "mculib" then
        host.mculib
      else if config.libc == "glibc" then
        host.glibc
      else if config.libc == "musl" then
        host.musl
      else
